-- ====================================================================
-- SejarahWira  |  ERA 3: Rukun Negara  |  seed_era3.sql
-- 3 naratif (6 + 6 + 6 babak = 18 babak), setiap babak ada 1 quest, serta 50 soalan.
--
-- SETIAP naratif merangkumi enam topik yang sama: (1) latar belakang (MAGERAN, MAPEN, 13 Mei 1969, 4 Mac 1970),
-- (2) sebab Rukun Negara diperkenalkan (ekonomi, tempat tinggal, politik), (3) lima matlamat, (4) prinsip 1 dan 2,
-- (5) prinsip 3, 4 dan 5, (6) enam peranan. Naratif hanya berbeza pada tokoh, sudut pandang, watak sampingan dan cabaran.
--
-- Pelajar MERASUK jasad tokoh sebenar (peranan naratif):
--   Naratif 1 (Arahan dari Bilik Gerakan) = Tun Abdul Razak, Pengarah MAGERAN (NPC 5)
--   Naratif 2 (Pintu Rumah Rakyat)        = Tun V.T. Sambanthan (NPC 41)
--   Naratif 3 (Ikrar Satu Malaysia)       = Tunku Abdul Rahman (NPC 1)
-- Baris dialog tanpa penutur (npcID NULL) ialah baris "Pemain" / "kau" yang dituturkan tokoh peranan.
-- Baris naratif tanpa babak (sceneID NULL): 1 = tugas bersejarah, 2 = pembuka pengajaran,
--   3 = pengenalan peranan oleh Pendekar Bayang.
-- Setiap quest ada "aftermath" (Akibat jika salah), pilihan salah jenis 3/5 ada "consequence",
-- dan satu "Giliran Anda" (turns). Data sahaja (tiada jadual atau lajur baharu).
-- Lencana, artifak dan kemajuan era TIDAK disentuh.
--
-- Jalankan SELEPAS seed.sql (NPC 1 dan 5 dibuat oleh seed.sql / seed_era1.sql):
--   mysql --default-character-set=utf8mb4 -u root -p <nama_db> < database/seed_era3.sql
-- Selamat dijalankan berulang kali (kandungan Era 3 lama dipadam dahulu). Era lain tidak disentuh.
--
-- NOTA GAMBAR: gambar prinsip_rukun_negara_.png mempunyai garis bawah di hujung nama (ikut nama fail anda).
-- ====================================================================
SET NAMES utf8mb4;
START TRANSACTION;

-- 1. Buang kandungan Era 3 lama (babak, dialog, quest, sokongan dipadam sekali: ON DELETE CASCADE).
DELETE FROM Narrative WHERE eraID = 3;

-- 2. NPC baharu Era 3 (nama fail gambar mengikut folder npc sebenar).
ON DUPLICATE KEY UPDATE name = VALUES(name), biography = VALUES(biography), contribution = VALUES(contribution), asset = VALUES(asset);

-- 3. Naratif

-- 4. Babak (sceneStoryline = kad garis masa dalam suara "kau"; asset = latar belakang)

-- 5. Quest (1 Susun Garis Masa, 2 Cari Bukti, 3 Bantu Tokoh, 4 Padanan, 5 Nyahkod Clue)
--    instruction = taklimat misi, description = objektif pembelajaran

-- 6. Sokongan: baris babak = petunjuk babak; baris quest = bisikan (hint), catatan diari (explanation), pujian (feedback)

-- 7. Dialog: baris peranan (tanpa babak) dan dialog babak

-- 8. Bank soalan Era 3 (50 soalan aneka pilihan, ID 301-350)
ON DUPLICATE KEY UPDATE eraID = VALUES(eraID);

DELETE FROM Question WHERE bankID = 3;


COMMIT;